/* Dune — spice sand, monumental thin display, desert silence */
.theme-dune {
  --bg: oklch(0.884 0.040 82.3);
  --surface: oklch(0.922 0.030 83.6);
  --surface-2: oklch(0.843 0.049 81.5);
  --fg: oklch(0.280 0.029 64.0);
  --fg-muted: oklch(0.536 0.043 73.2);
  --accent: oklch(0.491 0.101 54.4);
  --accent-fg: oklch(0.934 0.027 83.5);
  --accent-2: oklch(0.664 0.083 77.4);
  --line: oklch(0.790 0.053 83.3);
  --success: oklch(0.567 0.074 127.8);
  --warning: oklch(0.691 0.129 75.7);
  --danger: oklch(0.496 0.143 36.5);
  --radius: 0.125rem;
  --radius-sm: 0px;
  --radius-lg: 0.25rem;
  --radius-pill: 0.25rem;
  --shadow-1: 0 1px 2px oklch(0 0 0 / 8%);
  --shadow-2: 0 6px 20px -8px oklch(0 0 0 / 15%);
  --shadow-3: 0 20px 50px -16px oklch(0 0 0 / 20%);
  --glow: 0 0 0 1px color-mix(in oklab, var(--accent) 45%, transparent);
  --border-width: 1px;
  --blur-amount: 0px;
  --font-display: "Julius Sans One", sans-serif;
  --font-body: "Inter", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
  --tracking-display: 0.22em;
  --label-transform: uppercase;
  --label-tracking: 0.3em;

  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-dune h1,
.theme-dune h2,
.theme-dune h3 {
  font-family: var(--font-display);
  letter-spacing: var(--tracking-display);
}

/* signature */
.theme-dune { background-image: linear-gradient(180deg, transparent 60%, oklch(0.75 0.06 75 / 25%)), radial-gradient(ellipse at 80% 0%, oklch(0.95 0.04 85 / 60%), transparent 50%); }
.theme-dune h1 { font-size: clamp(2.6rem, 6vw, 4.6rem) !important; }
.theme-dune h2 { border-bottom: 1px solid var(--fg); display: inline-block; padding-bottom: 0.3em; }
.theme-dune button { letter-spacing: 0.24em; text-transform: uppercase; }

/* alt-mode — Arrakis night: deep desert dark, spice ember accent, Eyes of Ibad blue */
.theme-dune.alt-mode {
  --bg: oklch(0.185 0.022 60.0);
  --surface: oklch(0.230 0.026 62.0);
  --surface-2: oklch(0.280 0.032 64.0);
  --fg: oklch(0.900 0.035 82.0);
  --fg-muted: oklch(0.640 0.040 74.0);
  --accent: oklch(0.700 0.140 60.0);
  --accent-fg: oklch(0.160 0.020 60.0);
  --accent-2: oklch(0.680 0.110 240.0);
  --line: oklch(0.75 0.06 75 / 25%);
  --success: oklch(0.680 0.090 128.0);
  --warning: oklch(0.760 0.130 78.0);
  --danger: oklch(0.620 0.170 36.0);
  --shadow-1: 0 2px 6px oklch(0 0 0 / 40%);
  --shadow-2: 0 8px 24px oklch(0 0 0 / 50%);
  --shadow-3: 0 24px 56px oklch(0 0 0 / 60%);
  --glow: 0 0 0 1px color-mix(in oklab, var(--accent) 55%, transparent);
  background-image:
    linear-gradient(180deg, transparent 55%, oklch(0.28 0.05 55 / 45%)),
    radial-gradient(ellipse at 75% 8%, oklch(0.40 0.08 60 / 35%), transparent 45%);
}
.theme-dune.alt-mode h2 { border-bottom-color: var(--accent); }


/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);
}
